package router

import (
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/agentstation/starmap"
	"github.com/agentstation/starmap/pkg/catalogs"
	runtimecatalog "github.com/agentstation/starport/internal/catalog"
	"github.com/agentstation/starport/internal/providers/connectors"
)

// This audit benchmark isolates the actual catalog planning adapter. It does
// not call a provider or measure HTTP, authentication, or shared storage.
func BenchmarkAuditCatalogSelection(b *testing.B) {
	for _, count := range []int{10, 100, 1000} {
		b.Run(fmt.Sprintf("routes_%d", count), func(b *testing.B) {
			builder := catalogs.NewEmpty()
			must := func(err error) {
				if err != nil {
					b.Fatal(err)
				}
			}
			must(builder.SetAuthor(catalogs.Author{ID: "author", Name: "Author"}))
			features := &catalogs.ModelFeatures{Modalities: catalogs.ModelModalities{Input: []catalogs.ModelModality{catalogs.ModelModalityText}, Output: []catalogs.ModelModality{catalogs.ModelModalityText}}}
			models := make(map[string]*catalogs.Model, count)
			for i := 0; i < count; i++ {
				id := fmt.Sprintf("model-%04d", i)
				must(builder.SetAuthorModel("author", catalogs.Model{ID: id, Name: id, Authors: []catalogs.Author{{ID: "author", Name: "Author"}}, Features: features, Metadata: &catalogs.ModelMetadata{}}))
				models[id] = &catalogs.Model{ID: id, ModelRef: catalogs.ModelDefinitionID("author/" + id), Name: id, Status: catalogs.ModelStatusActive, Features: features, Metadata: &catalogs.ModelMetadata{}}
			}
			must(builder.SetProvider(catalogs.Provider{ID: "acme", Name: "Acme", Inference: &catalogs.ProviderInference{BaseURL: "https://example.invalid", Endpoints: []catalogs.ProviderInferenceEndpoint{{Operation: catalogs.ProviderOperationChatCompletions, Type: catalogs.EndpointTypeOpenAI, Path: "/v1/chat/completions"}}}, Models: models}))
			catalog, err := builder.Build()
			must(err)
			plane, err := runtimecatalog.Open(endpointBindingCatalogSource{state: starmap.CatalogState{Catalog: catalog, GenerationID: "latency-audit", Sequence: 1, GeneratedAt: time.Now()}})
			must(err)
			must(plane.SetAdapter(runtimecatalog.AdapterAvailability{ProviderID: "acme", Registered: true, Operations: []catalogs.ProviderOperation{catalogs.ProviderOperationChatCompletions}, EndpointTypes: []catalogs.EndpointType{catalogs.EndpointTypeOpenAI}}))
			if got := len(plane.Current().Routes()); got != count {
				b.Fatalf("expected %d routes, got %d", count, got)
			}
			connector := connectors.NewMockConnector(connectors.ProviderConfig{})
			route := New(&mockRegistry{connectors: map[string]connectors.Connector{"acme": connector}}, WithCatalog(plane))
			request := &Request{ChatRequest: &connectors.ChatRequest{Model: "author/model-0000", Messages: []connectors.Message{{Role: connectors.RoleUser, Content: "hello"}}}}
			ctx := context.Background()
			selected, _, err := route.SelectModel(ctx, request)
			must(err)
			if selected != "acme/model-0000" {
				b.Fatalf("unexpected route %q", selected)
			}
			b.ReportAllocs()
			for b.Loop() {
				if _, _, err := route.SelectModel(ctx, request); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}

// The released embedded catalog checks the same selection path with real facts.
func BenchmarkAuditEmbeddedOpenAISelection(b *testing.B) {
	client, err := starmap.New()
	if err != nil {
		b.Fatal(err)
	}
	plane, err := runtimecatalog.Open(client)
	if err != nil {
		b.Fatal(err)
	}
	err = plane.SetAdapter(runtimecatalog.AdapterAvailability{ProviderID: "openai", Registered: true, Operations: []catalogs.ProviderOperation{catalogs.ProviderOperationChatCompletions}, EndpointTypes: []catalogs.EndpointType{catalogs.EndpointTypeOpenAI}})
	if err != nil {
		b.Fatal(err)
	}
	routes := plane.Current().Routes()
	if len(routes) == 0 {
		b.Fatal("no routable OpenAI chat offering")
	}
	connector := connectors.NewMockConnector(connectors.ProviderConfig{})
	route := New(&mockRegistry{connectors: map[string]connectors.Connector{"openai": connector}}, WithCatalog(plane))
	request := &Request{ChatRequest: &connectors.ChatRequest{Model: string(routes[0].DefinitionID), Messages: []connectors.Message{{Role: connectors.RoleUser, Content: "hello"}}}}
	ctx := context.Background()
	if _, _, err := route.SelectModel(ctx, request); err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	for b.Loop() {
		if _, _, err := route.SelectModel(ctx, request); err != nil {
			b.Fatal(err)
		}
	}
	b.ReportMetric(float64(len(routes)), "routes")
}
